const { z } = require("zod");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const schema = z.record(z.string(), z.string());
const input = { key: "value" };
Object.defineProperty(input, "hidden", { value: 123, enumerable: false });
const r = schema.safeParse(input);
if (!r.success) {
  const iss = r.error.issues;
  if (iss.length === 1 && iss[0].path.length === 1 && iss[0].path[0] === "hidden") symptom("z.record rejects a non-enumerable own property");
  broken("unexpected issues: " + JSON.stringify(iss));
}
if (JSON.stringify(r.data) !== JSON.stringify({ key: "value" }) || Object.prototype.hasOwnProperty.call(r.data, "hidden")) broken("unexpected output: " + JSON.stringify(r.data));
if (schema.safeParse({ key: 1 }).success) broken("z.record accepted an enumerable invalid value");
console.log("OK: z.record skips non-enumerable own properties");

